  ('zcrm_5797994000003675019', 'Kalm Therapeutics', 'Kalm Therapeutics', 'Madhav Jami', 'Anuj Singhal', 'Developer of a prescription patch system designed to protect sensitive skin and deliver calming support for eczema and psoriasis. The company offers an all-natural, long-lasting adhesive patch that shields skin from irritation and releases an anti-inflammatory molecule over time, enabling individuals with chronic inflammatory skin conditions to experience steadier comfort and reduced flare-ups.', 'HV STEM', 'Healthcare', 'Spring 2026', NULL, 'Reached Out', 'Madhav Jami', 'Rejected', NULL, 'Founder Not Interested', NULL, '2026-02-06 05:40:40', '2026-02-13 07:41:03', '2026-02-13 07:41:03'),
  ('zcrm_5797994000003675045', 'BreakBio', 'BreakBio', 'Madhav Jami', 'Roy Souza', 'Operator of a biopharmaceutical platform intended to deliver personalized cancer immunotherapy for precise and targeted treatment. The company offers AI-driven, patient-specific peptide vaccines and medications that stimulate T-cell responses against non-mutated cancer targets, enabling individuals with solid tumors to receive tailored therapies that the immune system would not naturally initiate.', 'HV STEM', 'Healthcare', 'Spring 2026', NULL, 'Reached Out', 'Madhav Jami', 'Rejected', NULL, 'Vertical/Thesis Fit', NULL, '2026-02-06 05:54:56', '2026-02-12 12:05:40', '2026-02-12 12:05:40'),
  ('zcrm_5797994000003684013', 'Mensura health', 'Mensura Health', 'Zachary Christinat', 'General Email N/A', 'Operator of a biotechnological firm intended to offer therapeutic drug monitoring tools. The company offers electrochemical-based biosensors aptamer technology for rapid and accurate therapeutic drug monitoring of small molecule drug levels at the point of care, enabling clients to improve the effectiveness of existing medications.', 'HV STEM', 'Healthcare', 'Spring 2026', NULL, 'Reached Out', 'Zachary Christinat', 'Source', NULL, NULL, NULL, '2026-02-06 06:04:11', '2026-02-06 06:04:11', NULL),
  ('zcrm_5797994000003684039', 'Ronawk', 'Ronawk', 'Zachary Christinat', 'A.J. Mellot', 'Operator of a biotechnology company focused on preserving primary cells from patients for later use in reconstructive surgeries. The company''s technology provides a method to grow cells in a third-dimensional environment while maintaining characteristics of the cell population outside of the body, enabling researchers and clinicians to grow human cells efficiently and at high densities for tissue generation and disease modeling.', 'HV STEM', 'Healthcare', 'Spring 2026', NULL, 'Reached Out', 'Zachary Christinat', 'Source', NULL, NULL, NULL, '2026-02-06 06:11:28', '2026-02-06 06:11:28', NULL),
  ('zcrm_5797994000003684065', 'Laguna Tech', 'Laguna Tech', 'Zachary Christinat', 'Gilbert Madrid', 'Developer of heart valve replacement technology designed to revolutionize treatment options for aortic stenosis and regurgitation. The company''s device combines the benefits of balloon-expandable and self-expanding technologies, offering features like simplicity, reliability, and precise deployment, enabling medical professionals to provide improved patient outcomes through minimally invasive procedures.', 'HV STEM', 'Healthcare', 'Spring 2026', NULL, 'Reached Out', 'Zachary Christinat', 'Source', NULL, NULL, NULL, '2026-02-06 06:26:38', '2026-02-06 06:26:38', NULL),
  ('zcrm_5797994000003684091', 'Definitive Diagnostics', 'Definitive Diagnostics', 'Zachary Christinat', 'Ellis Malovany', 'Developer of a blood test platform designed to detect cancer by analyzing unique protein biomarker patterns for early and accurate diagnosis. The company offers patented protein-based technology enhanced with advanced artificial intelligence, enabling healthcare providers to detect cancers like breast, lung, colorectal, ovarian, and pancreatic early, improving diagnostic accuracy and patient outcomes.', 'HV STEM', 'Healthcare', 'Spring 2026', NULL, 'Reached Out', 'Zachary Christinat', 'Rejected', NULL, NULL, NULL, '2026-02-06 06:49:42', '2026-02-13 19:29:14', '2026-02-13 19:29:14'),
  ('zcrm_5797994000003684117', 'Accufix Surgical', 'Accufix Surgical', 'Zachary Christinat', 'John Evans', 'Developer of an anatomically restoring toe joint system designed to enhance mobility and preserve joint integrity for individuals with arthritic toe conditions. The company offers a bone-sparing, minimal weight-bearing implant that restores natural motion to the metatarsophalangeal joint, enabling individuals with Hallux Rigidus and Hallux Limitus to stay active and avoid joint-destructive procedures.', 'HV STEM', 'Healthcare', 'Spring 2026', NULL, 'Reached Out', 'Zachary Christinat', 'Source', NULL, NULL, NULL, '2026-02-06 06:59:15', '2026-02-06 06:59:15', NULL),
  ('zcrm_5797994000003684166', 'Kai Health', 'Kai', 'Zachary Christinat', 'General Contact', 'Developer of an AI-powered clinical performance improvement platform designed to reduce diagnostic errors and enhance revenue integrity in healthcare. The company''s platform conducts retrospective analysis of medical notes against evidence-based RSQ indicators, fee-for-service metrics, and value-based care measures, enabling healthcare providers to receive real-time clinical decision support to identify documentation gaps during patient encounters, generate personalized training modules based on individual provider performance, and access intelligent care navigation for referral management.', 'HV STEM', 'Healthcare', 'Spring 2026', NULL, 'Reached Out', 'Zachary Christinat', 'Source', NULL, NULL, NULL, '2026-02-08 10:37:38', '2026-02-16 05:58:46', '2026-02-16 05:58:46'),
