  ('zcrm_5797994000003694067', 'DataLane', 'DataLane', 'Soham Shah', 'David Patterson-Cole', 'Developer of a data-driven revenue system designed for companies serving deskless industries. The company''s platform includes a foundational knowledge graph, an adaptive targeting engine, and a unified system of action, enabling healthcare, retail, hospitality, and similar sectors to accelerate their go-to-market processes with improved targeting, contextual insights, and streamlined execution.', 'HV Genesis', 'Financial Innovation', 'Spring 2026', 'Pitchbook', 'Reached Out', 'Soham Shah', 'Source', 'Financial Innovation', NULL, NULL, '2026-02-08 12:12:00', '2026-02-08 12:12:00', '2026-02-08 12:12:00'),
  ('zcrm_5797994000003694102', 'Nixtla', 'Nixtla', 'Soham Shah', 'Cristian Challu', 'Developer of a software development platform designed to let developers and data scientists build open-source forecasting software. The company''s platform allows users to set up their time series processing service in the cloud and uses continuous integration and deployment to deploy the APIs on the company''s infrastructure, enabling clients to create features at the time series level and also at the temporal level.', 'HV Genesis', 'Financial Innovation', 'Spring 2026', 'Pitchbook', 'Reached Out', 'Soham Shah', 'Source', 'Financial Innovation', NULL, NULL, '2026-02-08 12:14:37', '2026-02-08 12:14:38', '2026-02-08 12:14:38'),
  ('zcrm_5797994000003694138', 'Prisidio', 'Prisidio', 'Soham Shah', 'Glenn Shimkus', 'Developer of a private and secure cloud digital vault designed to capture and securely share important information with key people. The company''s platform takes control of vital information in today''s complex and hectic digital age by providing a user-friendly interface, a mobile app, and security features that are a secure blend of privacy and protection, along with sharing, enabling people to organize their lives and affairs for retirement, business ventures, estate planning, or any unforeseen life events.', 'HV Genesis', 'Financial Innovation', 'Spring 2026', 'Pitchbook', 'Reached Out', 'Soham Shah', 'Source', 'Financial Innovation', NULL, NULL, '2026-02-08 12:20:35', '2026-02-08 12:20:36', '2026-02-08 12:20:36'),
