  ('zcrm_5797994000003706858', 'Siloam Vision', 'Siloam', 'Amelia Chapin', 'J Campbell', 'Developer of a comprehensive eye care platform designed to reduce preventable blindness and improve population health worldwide. The company offers AI-powered diagnostic tools, wide-field retinal imaging devices, and collaborative care software, enabling healthcare providers in underserved regions to detect and manage vision-threatening diseases at early stages.', 'HV STEM', 'Healthcare', 'Spring 2026', NULL, 'Have not Reached out', 'Amelia Chapin', 'Source', NULL, NULL, NULL, '2026-02-17 16:35:56', '2026-02-17 16:35:56', NULL),
  ('zcrm_5797994000003706884', 'Step in Health', 'Step in Health', 'Amelia Chapin', 'Nathan Lucht', 'Operator of a health and wellness platform for real-time hormone sensing intended to power the next generation of AI-enabled healthcare that is personalized, proactive and data-driven. The company is currently operating in stealth mode.', 'HV STEM', 'Healthcare', 'Spring 2026', NULL, 'Have not Reached out', 'Amelia Chapin', 'Source', NULL, NULL, NULL, '2026-02-17 16:39:02', '2026-02-17 16:39:02', NULL),
