  ('zcrm_5797994000003707085', 'Genabot', 'Genabot', 'Amal Abbasi', 'Jim Huang', 'Developer of advanced hardware and software platforms designed to enhance efficiency, yield, and quality in semiconductor manufacturing. The company offers AI-driven analytics, smart sensors, tailored support, and continuous innovation, enabling semiconductor manufacturers to optimize production processes, improve operational reliability, drive sustainable growth, and competitiveness.', 'HV STEM', 'Manufacturing Technology', 'Spring 2026', NULL, 'Have not Reached out', 'Amal Abbasi', 'Source', NULL, NULL, NULL, '2026-02-10 18:04:55', '2026-02-10 18:04:55', NULL),
  ('zcrm_5797994000003707116', 'Positron', 'Positron', 'Amal Abbasi', 'Sohmers', 'Developer of custom hardware designed to accelerate machine learning applications, focusing on end-to-end appliances for generative artificial intelligence models. The company specializes in building next-generation hardware and software appliances that deliver vendor freedom and better inference for enterprises and research teams, enabling clients to access improved hardware models to integrate into their systems.', 'HV STEM', 'Manufacturing Technology', 'Spring 2026', NULL, 'Have not Reached out', 'Amal Abbasi', 'Source', NULL, NULL, NULL, '2026-02-10 18:16:02', '2026-02-10 18:16:02', NULL),
  ('zcrm_5797994000003707147', 'AIStorm', 'AIStorm', 'Amal Abbasi', 'Barker', 'AIStorm, founded in 2018 and based in Houston, develops AI-in-sensor processing technology aimed at reducing latency, power consumption, and costs associated with edge computing. The company has 24 employees.', 'HV STEM', 'Manufacturing Technology', 'Spring 2026', NULL, 'Have not Reached out', 'Amal Abbasi', 'Source', NULL, NULL, NULL, '2026-02-10 18:18:58', '2026-02-10 18:18:58', NULL),
  ('zcrm_5797994000003707173', 'CURVE Sports', 'CURVE Sports', 'Mia Dansby', 'tom judge', 'CURVE Sports is a baseball-first ecosystem designed to improve how youth players are developed, supported, tracked, and connected with opportunities, bringing together clubs, athletes, families, standards, and data into a cohesive system.', 'HV Genesis', 'Sports and Wellness', 'Spring 2026', NULL, 'Have not Reached out', 'mia dansby', 'Source', 'Sports & Wellness', NULL, NULL, '2026-02-11 03:23:02', '2026-02-11 03:23:02', '2026-02-11 03:23:02'),
  ('zcrm_5797994000003707208', 'Next Gen Professionals', 'Next Gen Professionals', 'Mia Dansby', 'Andrew Welles', 'support the next generation of emerging professionals in the equestrian world. Our innovative model connects investors with talented riders in a mutually beneficial structure that offers returns for both parties.', 'HV Genesis', 'Sports and Wellness', 'Spring 2026', NULL, 'Reached Out', 'Mia Dansby', 'Source', 'Sports & Wellness', NULL, NULL, '2026-02-11 03:25:40', '2026-02-11 03:25:40', '2026-02-11 03:25:40'),
  ('zcrm_5797994000003707248', 'Vamos Racquets', 'Vamos Racquets', 'Mia Dansby', 'Katherine Lynch', 'Padel, pickleball, wellness, and events designed to keep you active and connected.', 'HV Genesis', 'Sports and Wellness', 'Spring 2026', NULL, 'Have not Reached out', 'Mia Dansby', 'Source', 'Sports & Wellness', NULL, NULL, '2026-02-11 03:31:23', '2026-02-11 03:31:24', '2026-02-11 03:31:24'),
  ('zcrm_5797994000003707283', 'Beyond Pulse', 'Beyond Pulse', 'Mia Dansby', 'Marc Maillet', 'Each player wears a Beyond Pulse Smart Belt at every session and the BP fitness activity tracker takes care of the rest. As the team trains, the lightweight sensor collects player and team data to report key development metrics.', 'HV Genesis', 'Sports and Wellness', 'Spring 2026', NULL, 'Have not Reached out', 'Mia Dansby', 'One Pager', 'Sports & Wellness', NULL, NULL, '2026-02-11 03:34:38', '2026-03-23 04:27:32', '2026-03-23 04:27:32'),
  ('zcrm_5797994000003707339', 'Dance Church', 'Dance Church', 'Joseph Martel', 'Kate Wallich', 'Dance Church® offers joyful, high-energy dance classes for people of all backgrounds to move, connect, and sweat in community. Founded in 2010 by choreographer Kate Wallich, Dance Church offers in-person classes in cities across the U.S. and a digital platform for on-demand movement experiences.', 'HV Genesis', 'Sports and Wellness', 'Spring 2026', NULL, 'Reached Out', 'Joe Martel', 'Source', 'Sports & Wellness', NULL, NULL, '2026-02-11 17:34:25', '2026-02-11 17:34:25', '2026-02-11 17:34:25'),
  ('zcrm_5797994000003707379', 'Varsity Hype', 'Varsity Hype', 'Joseph Martel', 'Jeffrey Wise', 'Effortless live streaming, simplified. Capturing life’s most important moments shouldn’t be a challenge. Yet, live streaming often turns into a logistical maze—complicated by equipment demands, unreliable internet, and the need for extra volunteers. Varsity Hype takes the hassle out of the equation. With our all-in-one solutions, we providecutting-edge cameras and technology at no upfront cost, making it easier than ever to stream and relive your biggest moments - stress-free.​', 'HV Genesis', 'Sports and Wellness', 'Spring 2026', NULL, 'Reached Out', 'Joe Martel', 'Source', 'Sports & Wellness', NULL, NULL, '2026-02-11 17:40:52', '2026-02-11 17:40:52', '2026-02-11 17:40:52'),
  ('zcrm_5797994000003707419', 'Stellar Sleep', 'Stellar Sleep', 'Joseph Martel', 'Edrei Chua', 'Stellar Sleep offers the first digital solution for chronic insomnia management. 25 million Americans suffer from chronic insomnia, defined as sleep problems 3+ nights a week for 3+ months. Superficial approaches such as meditation or melatonin don’t help with chronic insomnia, which is typically rooted in deeper psychological challenges. StellarSleep was founded by two chronic insomnia sufferers who grew frustrated with the lack of resources available to address their condition, and with the bad advice so many chronic insomniacs were getting.', 'HV Genesis', 'Sports and Wellness', 'Spring 2026', NULL, 'Reached Out', 'Joe Martel', 'Source', 'Sports & Wellness', NULL, NULL, '2026-02-11 17:49:13', '2026-02-11 17:49:13', '2026-02-11 17:49:13'),
  ('zcrm_5797994000003707469', 'PlayVision', 'PlayVision', 'Joseph Martel', 'Anish Gupta', 'PlayVision offers a platform that analyzes basketball game video, tracks player movements, and generates insights for coaches and scouts.', 'HV Genesis', 'Sports and Wellness', 'Spring 2026', NULL, 'Reached Out', 'Joe Martel', 'Source', 'Sports & Wellness', NULL, NULL, '2026-02-12 07:45:34', '2026-02-12 07:45:34', '2026-02-12 07:45:34'),
  ('zcrm_5797994000003707509', 'Selfmade', 'Selfmade', 'Joseph Martel', 'Stephanie Lee', 'Selfmade offers an emotional wellbeing brand created with mental health experts.', 'HV Genesis', 'Sports and Wellness', 'Spring 2026', NULL, 'Reached Out', 'Joe Martel', 'Source', 'Sports & Wellness', NULL, NULL, '2026-02-12 07:52:34', '2026-02-12 07:52:34', '2026-02-12 07:52:34'),
  ('zcrm_5797994000003707549', '98Strong', '98Strong', 'Joseph Martel', 'Andrew Mavis', '98Strong is a NIL (Name, Image, Likeness) marketing company founded in 2021 and based in Princeton, New Jersey. The company connects NCAA student athletes with brands looking to engage Gen Z audiences. It aims to empower all student athletes, particularly those who are often overlooked, by leveraging the collective brand power of many athletes to match or exceed the influence of individual professional athletes.', 'HV Genesis', 'Sports and Wellness', 'Spring 2026', NULL, 'Reached Out', 'Joe Martel', 'Source', 'Sports & Wellness', NULL, NULL, '2026-02-12 08:00:17', '2026-02-12 08:00:17', '2026-02-12 08:00:17'),
  ('zcrm_5797994000003707595', 'Miss Grass', 'Miss Grass', 'Joseph Martel', 'Kate Miller', 'Miss Grass is a modern and elevated online magazine with captivating content and an e-commerce destination for modern cannabis consumers. They share stories about the women who inspire and curate products for the women who define us. From cannabis basics to fitness, beauty to smoking etiquette, the war on drugs to healing lube, food to Mercury’sretrograde, This is your benevolent guide.', 'HV Genesis', 'Sports and Wellness', 'Spring 2026', NULL, 'Reached Out', 'Joe Martel', 'Source', 'Sports & Wellness', NULL, NULL, '2026-02-12 09:07:13', '2026-02-12 09:07:13', '2026-02-12 09:07:13'),
  ('zcrm_5797994000003707625', 'ColigoMed', 'ColigoMed', 'Zachary Christinat', 'Naidu Annamaneni', 'Developer a digital health platform designed to serve the healthcare industries. The company''s platform connects patients, caregivers, healthcare professionals, and health plan providers through data interoperability and offers features that include up-to-date patient data, proactively monitoring health readings, managing and storing health records, and AI-powered smart insights, enabling patients and doctors to meet their needs.', 'HV STEM', 'Healthcare', 'Spring 2026', 'PitchBook', 'Reached Out', 'Zachary Christinat', 'Source', NULL, NULL, NULL, '2026-02-12 09:14:58', '2026-02-12 09:14:58', NULL),
  ('zcrm_5797994000003707656', 'MM Brands Inc', 'MM Brands Inc', 'Joseph Martel', 'Natalie Farley', 'BellRock Brands Inc. is a multi-state cannabis consumer packaged goods (CPG) company based in Denver, Colorado. With over 10 years of industry experience, it operates a diverse portfolio of 11 established brands across nine THC markets in the United States.', 'HV Genesis', 'Sports and Wellness', 'Spring 2026', NULL, 'Reached Out', 'Joe Martel', 'Source', 'Sports & Wellness', NULL, NULL, '2026-02-12 09:22:38', '2026-02-12 09:22:38', '2026-02-12 09:22:38'),
  ('zcrm_5797994000003707698', 'UBsports Inc', 'UBsports Inc', 'Joseph Martel', 'Greg Burton', 'UBsports is the most inclusive, exciting community of amateur, Olympic and pro sports on the Web, where all athletes, coaches, their fans and their families meet and share their sports lives, no matter how young or old, what sport they play, how well they play it, or where they live.', 'HV Genesis', 'Sports and Wellness', 'Spring 2026', NULL, 'Reached Out', 'Joe Martel', 'Source', 'Sports & Wellness', NULL, NULL, '2026-02-12 11:14:32', '2026-02-12 11:14:32', '2026-02-12 11:14:32'),
  ('zcrm_5797994000003707733', 'Nephrogen', 'Nephrogen', 'Zachary Christinat', 'Demetri Maxim', 'Developer of gene delivery vectors designed to address challenges in creating genomic medicines for kidney and pancreatic diseases. The company integrates artificial intelligence and screening to engineer gene delivery vectors that improve efficiency, reduce immune response, and lower costs of genomic medicine, enabling researchers and clinicians to advance curative genomic therapies and improve patient outcomes.', 'HV STEM', 'Healthcare', 'Spring 2026', 'PitchBook', 'Reached Out', 'Zachary Christinat', 'Quick Screen', NULL, NULL, NULL, '2026-02-12 11:52:12', '2026-03-08 12:47:10', '2026-03-08 12:47:10'),
  ('zcrm_5797994000003707771', 'Helios', 'Helios', 'Joseph Martel', 'Bill Near', 'HELIOS® is a sports technology company based in Portsmouth, New Hampshire, founded in 2018. The company specializes in wearable sensors and AI-driven software designed to track and analyze hockey player and team performance. Their innovative sensor-to-cloud platform attaches to players'' shoulder pads, allowing for hardware-free tracking of skating metrics such as stride speed, agility, and total skating time.', 'HV Genesis', 'Sports and Wellness', 'Spring 2026', NULL, 'Reached Out', 'Joe Martel', 'Source', 'Sports & Wellness', NULL, NULL, '2026-02-13 06:20:25', '2026-02-13 06:20:25', '2026-02-13 06:20:25'),
  ('zcrm_5797994000003707807', 'Everbright Health', 'Everbright Health', 'Zachary Christinat', 'Ben Kuhn', 'Operator of a mental health treatment company intended to help individuals revive their mental conditions. The company specializes in leveraging technology for healing practices such as Transcranial Magnetic Stimulation, SPRAVATO, eligibility screening through electronic health records, automated patient engagement workflows, embedded staffing and equipment, and compliance and billing support, enabling patients to improve their behavioral health, streamline operational complexity for healthcare providers, and improve access to advanced psychiatric care for underserved patient populations.', 'HV STEM', 'Healthcare', 'Spring 2026', 'PitchBook', 'Reached Out', 'Zachary Christinat', 'Source', NULL, NULL, NULL, '2026-02-13 19:11:14', '2026-02-13 19:11:14', NULL),
  ('zcrm_5797994000003707834', 'Onos Health', 'Onos Health', 'Zachary Christinat', 'Josh Levitan', 'Developer of a behavioral health platform designed to streamline workflows and reduce administration tasks. The company''s platform transforms network management by automating documentation review, monitoring quality metrics, and providing AI-powered decision support that ensures consistent quality delivery across mental and behavioral health services while reducing administrative overhead, enabling healthcare institutions to minimize waste, streamline operations, and boost health outcomes.', 'HV STEM', 'Healthcare', 'Spring 2026', 'PitchBook', 'Reached Out', 'Zachary Christinat', 'Source', NULL, NULL, NULL, '2026-02-13 19:25:11', '2026-02-16 06:10:54', '2026-02-16 06:10:54'),
  ('zcrm_5797994000003707911', 'Headstart Health', 'Headstart Health', 'Zachary Christinat', 'Hasan Ismail', 'Operator of a behavioral health support platform intended for autism-focused therapy practices and families. The company''s platform equips independent clinicians with tools for practice formation, scheduling, documentation, and supervision management, offers coordination of insurance coverage and authorizations, supports ongoing parent training and progress tracking, and standardizes evidence-based treatment workflows, enabling behavioral health providers to operate sustainable, high-quality ABA practices while families access timely, structured therapeutic care.', 'HV STEM', 'Healthcare', 'Spring 2026', 'PitchBook', 'Reached Out', 'Zachary Christinat', 'Source', NULL, NULL, NULL, '2026-02-14 10:01:17', '2026-02-16 12:22:31', '2026-02-16 12:22:31'),
  ('zcrm_5797994000003707937', 'Encrycle', 'Encyrcle', 'Zachary Christinat', 'Ashly Stone', 'Developer of workflow automation software designed for behavioral health and substance abuse centers. The company''s system schedules recurring and custom outcome surveys to increase insurance reimbursements, personalize and automate post-discharge workflows, collect data, and perform risk assessments along with showcasing online reviews, enabling healthcare organizations to connect with their clients.', 'HV STEM', 'Healthcare', 'Spring 2026', NULL, 'Reached Out', 'Zachary Christinat', 'Source', NULL, NULL, NULL, '2026-02-14 10:19:06', '2026-02-16 12:22:38', '2026-02-16 12:22:38'),
  ('zcrm_5797994000003708000', 'Eighth Era Studios', 'Eighth Era Studios', 'Mia Dansby', 'Jordan lee', 'Developer of a mobile game platform intended to bridge the gap between digital gaming and physical ownership. The company''s platform operates as a mobile game developer and publisher that integrates physical numismatic collectibles into digital gameplay, enabling players to be rewarded with physical items like medals and coins, often certified by the Numismatic Guaranty Company.', 'HV Genesis', 'Sports and Wellness', 'Spring 2026', NULL, 'Reached Out', 'Mia Dansby', 'Source', 'Sports & Wellness', NULL, NULL, '2026-02-14 18:02:47', '2026-02-14 18:02:47', '2026-02-14 18:02:47'),
  ('zcrm_5797994000003708030', 'Saffron Tech', 'Saffron Tech', 'Joshua Kuteesa', 'Michael Oster', 'Developer of an agricultural technology designed to provide turnkey automated growing containers for the quality yield of saffron all year round. The company''s technology comes up with a mechanical and remotely managed system for growing saffron anywhere and anytime, providing automatic growth under laboratory conditions, facilitating quality output, and reducing cost, enabling saffron cultivators to get technology for the development of automatically growing containers that are remotely managed to ensure the supply of quality saffron throughout the year.', 'HV Genesis', 'Sustainability', 'Spring 2026', 'PitchBook', 'Reached Out', 'Joshua Kuteesa', 'Source', 'Sustainability', NULL, NULL, '2026-02-10 19:14:17', '2026-02-10 19:14:18', '2026-02-10 19:14:18'),
  ('zcrm_5797994000003708066', 'Kipostech', 'Kipostech', 'Joshua Kuteesa', 'Hema Ravindran', 'Developer of an air disinfection and intelligent air health monitoring platform designed to improve biosecurity and air quality in animal agriculture. The company offers chemical-free air treatment, real-time air health monitoring, and ventilation optimization, enabling poultry and livestock facilities to reduce airborne pathogens, ammonia, and particulate matter while supporting healthier production environments.', 'HV Genesis', 'Sustainability', 'Spring 2026', 'PitchBook', 'Reached Out', 'Joshua Kuteesa', 'Source', 'Sustainability', NULL, NULL, '2026-02-10 19:26:51', '2026-02-10 19:26:51', '2026-02-10 19:26:51'),
  ('zcrm_5797994000003708101', 'Viable Gear', 'Viable Gear', 'Joshua Kuteesa', 'Katie Weiler', 'Manufacturer of seaweed-based plastic alternatives intended to replace petroleum-based plastics in fishing, aquaculture, and agriculture. The company offers naturally derived, marine-compostable gear with performance comparable to traditional plastics, enabling food harvesters to reduce dependency on petroleum products, minimize ocean pollution, and prevent micro and nano plastics from entering food systems.', 'HV Genesis', 'Sustainability', 'Spring 2026', 'PitchBook', 'Reached Out', 'Joshua Kuteesa', 'Source', 'Sustainability', NULL, NULL, '2026-02-10 19:41:12', '2026-02-10 19:41:13', '2026-02-10 19:41:13'),
  ('zcrm_5797994000003708136', 'Terragrit', 'Terragrit', 'Joshua Kuteesa', 'Arthur Li', 'Developer of a no-code simulation platform designed to create virtual representations of physical spaces for virtual piloting and testing. The company offers collaborative simulation tools and configurable digital environments, enabling engineering teams and simulation users to design, test, and operate virtual pilots in controlled settings.', 'HV Genesis', 'Sustainability', 'Spring 2026', 'PitchBook', 'Reached Out', 'Joshua Kuteesa', 'Source', 'Sustainability', NULL, NULL, '2026-02-10 19:52:57', '2026-02-10 19:52:57', '2026-02-10 19:52:57'),
  ('zcrm_5797994000003708171', 'Green Grid', 'Green Grid', 'Joshua Kuteesa', 'Chinmoy Saha', 'Provider of an AI-enabled remote grid monitoring platform intended to improve the reliability, safety, and resilience of electric power infrastructure under growing climate and load pressures. The company offers AIoT line-mounted sensors, continuous autonomous monitoring software, and remote inspection services, enabling electric utilities to identify equipment faults, vegetation encroachment, and structural risks earlier, reduce outages and wildfire exposure, and manage grid assets more efficiently over long-term deployments.', 'HV Genesis', 'Sustainability', 'Spring 2026', 'PitchBook', 'Reached Out', 'Joshua Kuteesa', 'Source', 'Sustainability', NULL, NULL, '2026-02-10 20:04:06', '2026-02-10 20:04:06', '2026-02-10 20:04:06'),
  ('zcrm_5797994000003708322', 'Maywood Racquet Holdings', 'Maywood Racquet Holdings', 'Mia Dansby', 'Eric Udoff', 'Provider of indoor sports and coaching services intended for tennis and racket-sports engagement. The company offers a facility with seven indoor hard courts, pickleball access, equipment services such as stringing and grip replacement, a pro shop for rackets and apparel, enabling community members and visitors to access comprehensive instruction, organized play, flexible scheduling, and resource support that facilitate skill growth, recreational enjoyment, and year-round activity in a structured indoor environment', 'HV Genesis', 'Sports and Wellness', 'Spring 2026', NULL, 'Reached Out', 'Mia Dansby', 'Source', 'Sports & Wellness', NULL, NULL, '2026-02-17 05:01:39', '2026-02-17 05:01:39', '2026-02-17 05:01:39'),
  ('zcrm_5797994000003708357', 'GolfCard', 'GolfCard', 'Mia Dansby', 'Seth Meyer', 'Provider of a rewards-based credit card service designed for golf enthusiasts. The company offers credit card with a points-based rewards system, access to golf experiences, points on purchases to play courses, and concierge services, enabling golfers to convert everyday spending into valuable golfing opportunities and tailored lifestyle benefits.', 'HV Genesis', 'Sports and Wellness', 'Spring 2026', NULL, 'Reached Out', 'Mia Dansby', 'Source', 'Sports & Wellness', NULL, NULL, '2026-02-17 05:07:08', '2026-02-17 05:07:08', '2026-02-17 05:07:08'),
  ('zcrm_5797994000003708392', 'Dropback', 'Dropback', 'Mia Dansby', 'Luke Bogus', 'Developer of a front office software technology intended to help central athletic departments manage their teams'' salary caps and roster limits. The company''s technology integrates back-office tools with front-office strategies, featuring automated contract generation, custom financial models and dynamic athlete valuation tools, enabling teams to efficiently construct competitive rosters while saving time and ensuring data-driven decision-making that aligns with specific program priorities.', 'HV Genesis', 'Sports and Wellness', 'Spring 2026', NULL, 'Reached Out', 'Mia Dansby', 'Source', 'Sports & Wellness', NULL, NULL, '2026-02-17 05:09:41', '2026-02-17 05:09:41', '2026-02-17 05:09:41'),
  ('zcrm_5797994000003708427', 'Jolene Jolene', 'Jolene Jolene', 'Mia Dansby', 'Chelsea Fishman', 'Operator of a sports bar company intended for women sports. The company offers an inclusive space for everyone to enjoy themselves and feel welcomed, with a dedicated venue to showcase and celebrate sports, enabling women in professional and collegiate sports to access a place with good vibes and food while enjoying women''s sports.', 'HV Genesis', 'Sports and Wellness', 'Spring 2026', NULL, 'Reached Out', 'Mia Dansby', 'Connect', 'Sports & Wellness', NULL, NULL, '2026-02-17 05:12:28', '2026-02-22 02:55:03', '2026-02-22 02:55:03'),
