  ('zcrm_5797994000003708497', 'Golf Cooperative', 'Golf Cooperative', 'Mia Dansby', 'Aaron Gorman', 'Provider of indoor golf services intended to offer access to golf simulators and create community among owners. The company offers membership services, training and practice tools, customizable playing conditions, and analysis services, enabling golf enthusiasts to enjoy practice and social interaction at an affordable price.', 'HV Genesis', 'Sports and Wellness', 'Spring 2026', NULL, 'Reached Out', 'Mia Dansby', 'Source', 'Sports & Wellness', NULL, NULL, '2026-02-17 05:23:49', '2026-02-17 05:23:49', '2026-02-17 05:23:49'),
  ('zcrm_5797994000003708532', 'The Pad Tucson', 'The Pad Tucson', 'Mia Dansby', 'Riva Mackie', 'Operator of a racquet sports and fitness facility intended to provide experiences for all ages and skill levels. The company offers a range of services, including open play, leagues, clinics, tournaments, private and group lessons, junior programs, and free introductory classes, enabling players to improve their skills, enjoy social connections, and benefit from a comprehensive sports and wellness experience.', 'HV Genesis', 'Sports and Wellness', 'Spring 2026', NULL, 'Reached Out', 'Mia Dansby', 'Source', 'Sports & Wellness', NULL, NULL, '2026-02-17 05:25:38', '2026-02-17 05:25:38', '2026-02-17 05:25:38'),
  ('zcrm_5797994000003708568', 'PKLYN', 'PKLYN', 'Mia Dansby', 'David Friedman', 'Operator of a pickleball club intended to provide indoor courts and a community for competitive and casual pickleball players. The company has five professional indoor courts and provides bar and lounges, court rentals, drop-in facilities, leagues, tournaments, as well as coaching lessons, enabling pickleball enthusiasts to learn, practice, and enjoy a dedicated place to play pickleball and socialize.', 'HV Genesis', 'Sports and Wellness', 'Spring 2026', NULL, 'Reached Out', 'Mia Dansby', 'Source', 'Sports & Wellness', NULL, NULL, '2026-02-17 05:28:21', '2026-02-17 05:28:22', '2026-02-17 05:28:22'),
  ('zcrm_5797994000003709062', 'AOA', 'AOA', 'Rosemary Moyo', 'Oriana Papin-Zoghbi', 'AOA Dx is pioneering lipidomics to unlock the next generation of biomarkers for early cancer diagnosis. AOA Dx is developing the first and only technology utilizing these markers and other complimentary biomarkers with data science, providing remarkable insights into early cancer diagnosis.', 'HV STEM', 'Healthcare', 'Spring 2026', NULL, 'Reached Out', 'Rosemary Moyo', 'Source', NULL, NULL, NULL, '2026-02-10 17:40:54', '2026-02-10 17:40:54', NULL),
