  ('zcrm_5797994000003710511', 'ThreatCaptain', 'ThreatCaptain', 'Pranay Kakkar', 'Adam Anderson', 'Developer of a financial cyber risk platform designed to navigate securely with financial foresight. The company''s platform analyzes threat intelligence with precision, enhancing the ability to proactively safeguard client networks and assets by translating cybersecurity risks into financial terms using advanced algorithms and assessing economic impact and the likelihood of breaches using behavior patterns derived from known threats and industry frameworks, enabling clients with data impact-related compliance, insurance requirements, streamlining of reporting, guiding effective cybersecurity strategy and risk mitigation.', 'HV STEM', 'SaaS', 'Spring 2026', 'Pitchbook', 'Have not Reached out', 'Pranay Kakkar', 'Source', NULL, NULL, NULL, '2026-02-12 07:54:31', '2026-02-12 07:54:31', NULL),
  ('zcrm_5797994000003710537', 'Piris Labs', 'Piris Labs', 'Pranay Kakkar', 'Ali Khalatpour', 'Piris Labs offers a full-stack inference service that eliminates the AI data movement bottleneck. By pairing proprietary photonic hardware with a vertically optimized software stack, we minimize the "memory wall" associated with expensive GPUs. This allows us to deliver the same performance as traditional clusters at a fraction of the cost. Our technology improves effective FLOP utilization and reduces latency, finally making the unit economics of trillion-parameter models sustainable. Founded by a team of MIT physicists and Meta AI experts.', 'HV STEM', 'SaaS', 'Spring 2026', 'YCombinator', 'Reached Out', 'Pranay Kakkar', 'Source', NULL, NULL, NULL, '2026-02-12 08:56:38', '2026-02-12 08:56:38', NULL),
  ('zcrm_5797994000003710598', 'EntropiQ', 'EntropiQ', 'Pranay Kakkar', 'Josh Lewis', 'Provider of quantum entropy and endpoint cloaking technology intended to secure sensitive data and communications for critical infrastructure organizations. The company offers on-demand, elastic, high-performance, low-latency quantum entropy as a service, delivered with military-grade, crypto-agile endpoint protection, enabling organizations to safeguard data and communications against current and future threats.', 'HV STEM', 'SaaS', 'Spring 2026', 'Pitchbook', 'Have not Reached out', 'Pranay Kakkar', 'Source', NULL, NULL, NULL, '2026-02-15 09:19:18', '2026-02-15 09:19:18', NULL),
  ('zcrm_5797994000003710784', 'Tidalwave', 'Tidalwave', 'Markos Papakosmas', 'Diane Yu', 'Developer of an artificial intelligence-driven fintech platform designed to streamline the residential mortgage application process. The company''s platform utilizes agentic AI to automate condition mapping and task tracking, underwriting systems simultaneously for better loan outcomes, allowing independent mortgage banks and credit unions to significantly enhance mortgage originator efficiencies, increase loan close rates, and improve overall profitability.', 'HV Genesis', 'Financial Innovation', 'Spring 2026', 'Crunchbase', 'Reached Out', 'Markos Papakosmas', 'Source', 'Financial Innovation', NULL, NULL, '2026-02-17 04:56:07', '2026-02-17 04:56:07', '2026-02-17 04:56:07'),
  ('zcrm_5797994000003710819', 'Rox AI', 'Rox AI', 'Markos Papakosmas', 'Ishan Mukherjee', 'Developer of an artificial intelligence-powered sales productivity platform designed to help sales teams be more productive. The company''s platform unifies, processes and monitors all external and internal information about customers, enabling customers to find the information they need and take action, and also helps sales teams to create personalized emails and LinkedIn posts, track customer behavior, and uncover trends for best outcomes.', 'HV Genesis', 'Financial Innovation', 'Spring 2026', 'PitchBook', 'Reached Out', 'Markos Papakosmas', 'Source', 'Financial Innovation', NULL, NULL, '2026-02-17 05:05:32', '2026-02-17 05:05:32', '2026-02-17 05:05:32'),
